/* @lc app=leetcode id=984 lang=kotlin */ class Solution { fun strWithout3a3b(a: Int, b: Int): String = generateSequence(Triple(a, b, "")) { (x, y, s) -> if (x + y == 0) null else if (s.length >= 2 && s[s.length - 1] == s[s.length - 2]) (if (s.last() == 'a') Triple(x, y - 1, s + 'b') else Triple(x - 1, y, s + 'a')) else if (x >= y) Triple(x - 1, y, s + 'a') else Triple(x, y - 1, s + 'b') }.last().third }